linkList.script:
// 数据源名称
var db = "数据源名称";

// 获取部门名称
var Department = dept.Text;

// 如果部门信息为请选择或请输入，则提示输入部门信息
if (Department === '请选择' || Department === '请输入') {
    ShowMessage({
        'message': '请输入部门信息',
        type: 'warning'
    });
}

// 获取岗位名称、员工手机号、员工姓名、员工工号、当前日期时间、当前用户
var Position = pos.Text;
var Phone = phone.Text;
var Name = name.Text;
var JobNumber = GH.Text;
var DATE = new Date().format('yyyy-MM-dd hh:mm:ss');
var Creater = $System.CurrentUser;

// 如果当前用户为空或null或undefined
if (Creater === '' || Creater === null || Creater === undefined ) {
    Creater = GetCurrentUser();
}

// 获取技能级别、线体、班组信息
var Skill_Level = Skill_Level.GetCurrentText();
var line_code = line_code.GetCurrentText();
var work_shift = work_shift.GetCurrentText();

// 如果班组信息为空，则提示选择班组信息
if (work_shift === '') {
    ShowMessage({
        'message': '请选择班组信息',
        type: 'warning'
    });
}

// 检查是否所有必填信息都已填写
if (Department === '' || JobNumber === '' || Position === '' || Name === '' || DATE === '') {
    ShowMessage({
        'message': '不能为空，请输入完整信息',
        type: 'warning'
    });
} else {
    // 构建更新用户信息的 SQL 语句
    var sql = `UPDATE  更换自己的表名 SET  Department_name = '${Department}',
            user_code = '${JobNumber}',Position_name = '${Position}',Phone = '${Phone}',work_shift= '${work_shift}',
            user_name = '${Name}',Skill_Level='${Skill_Level}',g_xb='${line_code}',  CreatDate = '${DATE}',Creater='${Creater}' WHERE user_code = '${JobNumber}'`;

    // 执行 SQL 更新操作
    SQLExecute1(db, 1, sql, function(res) {
        if (res.errorCode === 0) {
            // 更新成功后，设置重新获取数据标志，显示成功提示，并关闭用户修改页面
            $System.$PicManager.用户管理.$Variable.reGetdata = false;
            var options = {
                message: "修改成功",
                type: 'success',
            };
            ShowMessage(options);
            ClosePage('用户修改');
        } else {
            // 更新失败，显示失败提示
            var options = {
                message: "修改失败",
                type: 'warning',
            };
            ShowMessage(options);
        }
    }, 5000); // 设置超时时间为 5000 毫秒
}

