linkList.script:
// 获取选定的设备详情数据
let dataArr = $System.$PicManager.用户管理.$Children.设备详情.GetSelections();

// 将部门名称填入dept文本框
dept.Text = dataArr[0].Department_name;

// 将员工工号填入GH文本框
GH.Text = dataArr[0].user_code;

// 将岗位名称填入pos文本框
pos.Text = dataArr[0].Position_name;

// 将员工手机号填入phone文本框
phone.Text = dataArr[0].Phone;

// 将员工姓名填入name文本框
name.Text = dataArr[0].user_name;

// 如果班次为空或者为null，则设为“无”，否则保持原值
if (dataArr[0].work_shift === '' || dataArr[0].work_shift === null) {
    dataArr[0].work_shift = '无';
}

// 将班次状态赋值给工作班次下拉框
$(work_shift.id).combobox('select', dataArr[0].work_shift);

